// 비싸다 — 레이아웃부터 다시
el.style.left = x + 'px';

// 싸다 — 합성만 (GPU 가 옮긴다)
el.style.transform = `translateX(${x}px)`;

// 투명도도 합성 단계
el.style.opacity = '0.5';

// 나쁨: 읽기(offsetWidth)가 매번 강제 레이아웃을 일으킨다
for (const el of items) el.style.width = el.offsetWidth + 10 + 'px';

// 좋음: 먼저 전부 읽고, 그 다음 전부 쓴다
const widths = items.map((el) => el.offsetWidth);
items.forEach((el, i) => { el.style.width = widths[i] + 10 + 'px'; });

function chunked(items, draw) {
  let i = 0;
  (function step() {
    const end = Math.min(i + 200, items.length);
    for (; i < end; i++) draw(items[i]);
    if (i < items.length) requestAnimationFrame(step);
  })();
}
